INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-ueno-7-60',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ อุเอโนะ (เอโดะ)',
        'The Golden Relic Stupa of Ueno (เอโดะ)',
        'sacred',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.7292,
        139.8031,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน โตเกียว (ญี่ปุ่น) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เอโดะ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Tokyo (Japan), serving as the spiritual heart of ancestral เอโดะ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค โตเกียว (ญี่ปุ่น) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Tokyo (Japan), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน อุเอโนะ',
        'Remove footwear and maintain silence within the inner terrace of Ueno.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-ueno-7-60',
        'วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ อุเอโนะ (เอโดะ)',
        'The White Lady Specter of Ueno (เอโดะ)',
        'ghost',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.7292,
        139.8031,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น โตเกียว (ญี่ปุ่น) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ อุเอโนะ',
        'A chilling paranormal account from Tokyo (Japan). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Ueno.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เอโดะ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เอโดะ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ อุเอโนะ',
        'Never whistle or look back if hearing whispers along twilight pathways in Ueno.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-ueno-7-60',
        'อสุรกายพญาเงาแห่งพงไพร อุเอโนะ (เอโดะ)',
        'The Shadow Beast of Ueno (เอโดะ)',
        'monster',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.7292,
        139.8031,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน โตเกียว (ญี่ปุ่น) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ อุเอโนะ',
        'Eyewitness reports of a formidable cryptid stalking Tokyo (Japan). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Ueno.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เอโดะ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เอโดะ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ อุเอโนะ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Ueno.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-ueno-7-60',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม อุเอโนะ (เอโดะ)',
        'The Inscribed Hex and Tragic Fate of Ueno (เอโดะ)',
        'curse',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.7292,
        139.8031,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง โตเกียว (ญี่ปุ่น) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน อุเอโนะ',
        'A grim cautionary curse chronicle from Tokyo (Japan). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Ueno.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เอโดะ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เอโดะ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ อุเอโนะ',
        'Never remove stones, relics, or votive offerings from Ueno.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-ueno-7-60',
        'มหาปราการหินเมกะลิธและแนวสุริยะ อุเอโนะ (เอโดะ)',
        'The Megalithic Solar Alignments of Ueno (เอโดะ)',
        'legend',
        'โตเกียว (ญี่ปุ่น)',
        'Tokyo (Japan)',
        'อุเอโนะ',
        'Ueno',
        35.7292,
        139.8031,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง โตเกียว (ญี่ปุ่น) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เอโดะ ใน อุเอโนะ',
        'A legendary monumental marvel in Tokyo (Japan). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เอโดะ engineers in Ueno.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ โตเกียว (ญี่ปุ่น) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Tokyo (Japan), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ อุเอโนะ',
        'Do not deface, carve, or displace ancient stones in Ueno.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ อุเอโนะ (เอโดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

