        'A venerated holy landmark of Hokkaido (Japan), serving as the spiritual heart of ancestral ไอนุ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ฮอกไกโด (ญี่ปุ่น) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Hokkaido (Japan), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โนโบริเบ็ตสึ',
        'Remove footwear and maintain silence within the inner terrace of Noboribetsu.',
        'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน ปูชนียสถานศักดิ์สิทธิ์และบารมีพระบรมธาตุ","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
