INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-noboribetsu-7-61',
        'พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก โนโบริเบ็ตสึ (ไอนุ)',
        'The Serpentine Deep Water Leviathan of Noboribetsu (ไอนุ)',
        'monster',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4417,
        141.0767,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ฮอกไกโด (ญี่ปุ่น) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ โนโบริเบ็ตสึ',
        'Eyewitness reports of a formidable cryptid stalking Hokkaido (Japan). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Noboribetsu.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ไอนุ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ไอนุ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ โนโบริเบ็ตสึ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Noboribetsu.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-noboribetsu-7-61',
        'วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง โนโบริเบ็ตสึ (ไอนุ)',
        'The Cursed Heirlooms and Bloodline Hex of Noboribetsu (ไอนุ)',
        'curse',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4417,
        141.0767,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ฮอกไกโด (ญี่ปุ่น) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน โนโบริเบ็ตสึ',
        'A grim cautionary curse chronicle from Hokkaido (Japan). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Noboribetsu.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ไอนุ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ไอนุ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ โนโบริเบ็ตสึ',
        'Never remove stones, relics, or votive offerings from Noboribetsu.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-noboribetsu-7-61',
        'นครโบราณที่สาบสูญใต้ผืนป่า โนโบริเบ็ตสึ (ไอนุ)',
        'The Lost Sunken Citadel of Noboribetsu (ไอนุ)',
        'legend',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4417,
        141.0767,
        'jungle_curse',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ฮอกไกโด (ญี่ปุ่น) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ไอนุ ใน โนโบริเบ็ตสึ',
        'A legendary monumental marvel in Hokkaido (Japan). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ไอนุ engineers in Noboribetsu.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ฮอกไกโด (ญี่ปุ่น) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Hokkaido (Japan), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ โนโบริเบ็ตสึ',
        'Do not deface, carve, or displace ancient stones in Noboribetsu.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"นครโบราณที่สาบสูญใต้ผืนป่า โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-jongno-7-62',
        'อารามโบราณพิทักษ์ผืนป่า จงโน (โชซอน)',
        'The Sacred Mountain Hermitage of Jongno (โชซอน)',
        'sacred',
        'โซล (เกาหลีใต้)',
        'Seoul (South Korea)',
        'จงโน',
        'Jongno',
        37.6178,
        126.9944,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน โซล (เกาหลีใต้) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว โชซอน เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Seoul (South Korea), serving as the spiritual heart of ancestral โชซอน heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค โซล (เกาหลีใต้) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Seoul (South Korea), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน จงโน',
        'Remove footwear and maintain silence within the inner terrace of Jongno.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า จงโน (โชซอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
