      ) VALUES (
        'pin-curse-seogwipo-7-63',
        'คำสาปแผ่นดินและเมืองร้างโบราณ ซอกวิโพ (ทัมราโบราณ)',
        'The Desolation Curse of Seogwipo (ทัมราโบราณ)',
        'curse',
        'เชจู (เกาหลีใต้)',
        'Jeju (South Korea)',
        'ซอกวิโพ',
        'Seogwipo',
        33.2092,
        126.515,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เชจู (เกาหลีใต้) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ซอกวิโพ',
        'A grim cautionary curse chronicle from Jeju (South Korea). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Seogwipo.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ทัมราโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ทัมราโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ซอกวิโพ',
        'Never remove stones, relics, or votive offerings from Seogwipo.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปแผ่นดินและเมืองร้างโบราณ ซอกวิโพ (ทัมราโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

