        'pin-legend-chengdu-7-64',
        'เส้นทางค้าโบราณและคาราวานปริศนา เฉิงตู (สู่ฮั่นโบราณ)',
        'The Ancient Silk Route Oasis of Chengdu (สู่ฮั่นโบราณ)',
        'legend',
        'เสฉวน (จีน)',
        'Sichuan (China)',
        'เฉิงตู',
        'Chengdu',
        30.6286,
        104.0647,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เสฉวน (จีน) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว สู่ฮั่นโบราณ ใน เฉิงตู',
        'A legendary monumental marvel in Sichuan (China). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral สู่ฮั่นโบราณ engineers in Chengdu.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เสฉวน (จีน) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Sichuan (China), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เฉิงตู',
        'Do not deface, carve, or displace ancient stones in Chengdu.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"เส้นทางค้าโบราณและคาราวานปริศนา เฉิงตู (สู่ฮั่นโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

