        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-ubud-7-66',
        'เสียงสะอื้นไห้ใต้สะพานหินโบราณ อูบุด (ฮินดูบาหลี)',
        'The Phantom Sobs Beneath Stone Bridge of Ubud (ฮินดูบาหลี)',
        'ghost',
        'บาหลี (อินโดนีเซีย)',
        'Bali (Indonesia)',
        'อูบุด',
        'Ubud',
        -8.5069,
        115.2475,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น บาหลี (อินโดนีเซีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ อูบุด',
        'A chilling paranormal account from Bali (Indonesia). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Ubud.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ฮินดูบาหลี ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ฮินดูบาหลี oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ อูบุด',
        'Never whistle or look back if hearing whispers along twilight pathways in Ubud.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"เสียงสะอื้นไห้ใต้สะพานหินโบราณ อูบุด (ฮินดูบาหลี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

