INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-ubud-7-66',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน อูบุด (ฮินดูบาหลี)',
        'The Bottomless Sacred Cenote of Ubud (ฮินดูบาหลี)',
        'legend',
        'บาหลี (อินโดนีเซีย)',
        'Bali (Indonesia)',
        'อูบุด',
        'Ubud',
        -8.5069,
        115.2475,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง บาหลี (อินโดนีเซีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ฮินดูบาหลี ใน อูบุด',
        'A legendary monumental marvel in Bali (Indonesia). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ฮินดูบาหลี engineers in Ubud.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ บาหลี (อินโดนีเซีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Bali (Indonesia), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ อูบุด',
        'Do not deface, carve, or displace ancient stones in Ubud.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน อูบุด (ฮินดูบาหลี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-mount-bromo-7-67',
        'เทวาลัยโบราณแห่งมหาเทวะ ภูเขาไฟโบรโม (มัชปาหิต)',
        'The Ancient Chola Shiva Shrine of Mount Bromo (มัชปาหิต)',
        'sacred',
        'ชวาตะวันออก (อินโดนีเซีย)',
        'East Java (Indonesia)',
        'ภูเขาไฟโบรโม',
        'Mount Bromo',
        -7.9275,
        112.9831,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ชวาตะวันออก (อินโดนีเซีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว มัชปาหิต เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of East Java (Indonesia), serving as the spiritual heart of ancestral มัชปาหิต heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ชวาตะวันออก (อินโดนีเซีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in East Java (Indonesia), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน ภูเขาไฟโบรโม',
        'Remove footwear and maintain silence within the inner terrace of Mount Bromo.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-mount-bromo-7-67',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ภูเขาไฟโบรโม (มัชปาหิต)',
        'The Will-o''-the-Wisp Ghost Light of Mount Bromo (มัชปาหิต)',
        'ghost',
        'ชวาตะวันออก (อินโดนีเซีย)',
        'East Java (Indonesia)',
        'ภูเขาไฟโบรโม',
        'Mount Bromo',
        -7.9275,
        112.9831,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ชวาตะวันออก (อินโดนีเซีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ภูเขาไฟโบรโม',
        'A chilling paranormal account from East Java (Indonesia). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Mount Bromo.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว มัชปาหิต ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of มัชปาหิต oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ภูเขาไฟโบรโม',
        'Never whistle or look back if hearing whispers along twilight pathways in Mount Bromo.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-mount-bromo-7-67',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด ภูเขาไฟโบรโม (มัชปาหิต)',
        'The Amphibious Troglodyte of Mount Bromo (มัชปาหิต)',
        'monster',
        'ชวาตะวันออก (อินโดนีเซีย)',
        'East Java (Indonesia)',
        'ภูเขาไฟโบรโม',
        'Mount Bromo',
        -7.9275,
        112.9831,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ชวาตะวันออก (อินโดนีเซีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ภูเขาไฟโบรโม',
        'Eyewitness reports of a formidable cryptid stalking East Java (Indonesia). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Mount Bromo.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว มัชปาหิต ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native มัชปาหิต folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ภูเขาไฟโบรโม',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Mount Bromo.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-mount-bromo-7-67',
        'อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม ภูเขาไฟโบรโม (มัชปาหิต)',
        'The Fatal Melody Hex of Mount Bromo (มัชปาหิต)',
        'curse',
        'ชวาตะวันออก (อินโดนีเซีย)',
        'East Java (Indonesia)',
        'ภูเขาไฟโบรโม',
        'Mount Bromo',
        -7.9275,
        112.9831,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ชวาตะวันออก (อินโดนีเซีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ภูเขาไฟโบรโม',
        'A grim cautionary curse chronicle from East Java (Indonesia). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Mount Bromo.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว มัชปาหิต เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of มัชปาหิต, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ภูเขาไฟโบรโม',
        'Never remove stones, relics, or votive offerings from Mount Bromo.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

