        'pin-sacred-baguio-7-68',
        'มหารัตนเจดีย์แห่งมโนธรรม บากีโอ (คอร์ดิลเลรา)',
        'The Great Jeweled Pagoda of Baguio (คอร์ดิลเลรา)',
