INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-imperial-hue-7-69',
        'พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Black-Scaled Serpent of Imperial Hue (ราชวงศ์เหงียน)',
        'monster',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.5087,
        107.6059,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เว้ (เวียดนาม) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ นครหลวงเว้',
        'Eyewitness reports of a formidable cryptid stalking Hue (Vietnam). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Imperial Hue.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ราชวงศ์เหงียน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ราชวงศ์เหงียน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ นครหลวงเว้',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Imperial Hue.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-imperial-hue-7-69',
        'อาถรรพ์รูปเคารพและดวงตาจ้องมอง นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Cursed Effigy Gaze of Imperial Hue (ราชวงศ์เหงียน)',
        'curse',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.5087,
        107.6059,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เว้ (เวียดนาม) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน นครหลวงเว้',
        'A grim cautionary curse chronicle from Hue (Vietnam). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Imperial Hue.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ราชวงศ์เหงียน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ราชวงศ์เหงียน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ นครหลวงเว้',
        'Never remove stones, relics, or votive offerings from Imperial Hue.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์รูปเคารพและดวงตาจ้องมอง นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-imperial-hue-7-69',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Undeciphered Glyph Stele of Imperial Hue (ราชวงศ์เหงียน)',
        'legend',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.5087,
        107.6059,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เว้ (เวียดนาม) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ราชวงศ์เหงียน ใน นครหลวงเว้',
        'A legendary monumental marvel in Hue (Vietnam). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ราชวงศ์เหงียน engineers in Imperial Hue.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เว้ (เวียดนาม) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Hue (Vietnam), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ นครหลวงเว้',
        'Do not deface, carve, or displace ancient stones in Imperial Hue.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-amarapura-8-70',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ อมรปุระ (คองบอง)',
        'The Golden Relic Stupa of Amarapura (คองบอง)',
        'sacred',
        'มัณฑะเลย์ (พม่า)',
        'Mandalay (Myanmar)',
        'อมรปุระ',
        'Amarapura',
        21.8567,
        96.0036,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน มัณฑะเลย์ (พม่า) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว คองบอง เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Mandalay (Myanmar), serving as the spiritual heart of ancestral คองบอง heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค มัณฑะเลย์ (พม่า) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Mandalay (Myanmar), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน อมรปุระ',
        'Remove footwear and maintain silence within the inner terrace of Amarapura.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ อมรปุระ (คองบอง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
