        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-angkor-wat-8-71',
        'เทวสถานศรัทธาแห่งแสงธรรม พระนครวัด (เขมรโบราณ)',
        'The Radiant Divine Sanctuary of Angkor Wat (เขมรโบราณ)',
        'sacred',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.3825,
        103.8667,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เสียมราฐ (กัมพูชา) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เขมรโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Siem Reap (Cambodia), serving as the spiritual heart of ancestral เขมรโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เสียมราฐ (กัมพูชา) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Siem Reap (Cambodia), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน พระนครวัด',
        'Remove footwear and maintain silence within the inner terrace of Angkor Wat.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
