        'pin-ghost-angkor-wat-8-71',
        'เงาร่างทมิฬแห่งหอระฆังร้าง พระนครวัด (เขมรโบราณ)',
        'The Dark Bell Tower Phantom of Angkor Wat (เขมรโบราณ)',
        'ghost',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.3825,
        103.8667,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น เสียมราฐ (กัมพูชา) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ พระนครวัด',
        'A chilling paranormal account from Siem Reap (Cambodia). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Angkor Wat.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เขมรโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เขมรโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ พระนครวัด',
        'Never whistle or look back if hearing whispers along twilight pathways in Angkor Wat.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เงาร่างทมิฬแห่งหอระฆังร้าง พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
