        'pin-curse-manali-8-72',
        'อาถรรพ์ทางแยกสัญญามนต์ดำ มะนาลี (เวทหิมาลัย)',
        'The Forbidden Crossroads Covenant of Manali (เวทหิมาลัย)',
        'curse',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2246,
        77.2337,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง หิมาจัลประเทศ (อินเดีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน มะนาลี',
        'A grim cautionary curse chronicle from Himachal Pradesh (India). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Manali.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เวทหิมาลัย เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เวทหิมาลัย, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ มะนาลี',
        'Never remove stones, relics, or votive offerings from Manali.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์ทางแยกสัญญามนต์ดำ มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
