      ) VALUES (
        'pin-legend-manali-8-72',
        'แท่นหินดาราศาสตร์และภูมิปัญญาบรรพกาล มะนาลี (เวทหิมาลัย)',
        'The Archaeoastronomical Stone Ring of Manali (เวทหิมาลัย)',
