      ) VALUES (
        'pin-sacred-york-8-76',
        'พระธาตุยอดเขาพันยอด ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Thousand-Spire Mountain Pagoda of York (ไวกิ้งยอร์วิก)',
