        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-york-8-76',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Bottomless Sacred Cenote of York (ไวกิ้งยอร์วิก)',
        'legend',
        'ยอร์กเชียร์ (อังกฤษ)',
        'Yorkshire (England)',
        'ยอร์ก',
        'York',
        54.0041,
        -1.0665,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ยอร์กเชียร์ (อังกฤษ) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ไวกิ้งยอร์วิก ใน ยอร์ก',
        'A legendary monumental marvel in Yorkshire (England). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ไวกิ้งยอร์วิก engineers in York.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ยอร์กเชียร์ (อังกฤษ) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Yorkshire (England), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ยอร์ก',
        'Do not deface, carve, or displace ancient stones in York.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน ยอร์ก (ไวกิ้งยอร์วิก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

