        'pin-ghost-curragh-8-78',
        'วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ เคอร์ราห์ (เกลิกไอริช)',
        'The Restless Keeper of Curragh (เกลิกไอริช)',
