        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-snowdonia-8-79',
        'มหาวิหารแห่งสันติภาพและศรัทธา สโนว์โดเนีย (เวลส์คิมรี)',
        'The Grand Peace Cathedral of Snowdonia (เวลส์คิมรี)',
        'sacred',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.0535,
        -4.0313,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน แคว้นเวลส์ (สหราชอาณาจักร) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เวลส์คิมรี เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Wales (United Kingdom), serving as the spiritual heart of ancestral เวลส์คิมรี heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค แคว้นเวลส์ (สหราชอาณาจักร) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Wales (United Kingdom), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน สโนว์โดเนีย',
        'Remove footwear and maintain silence within the inner terrace of Snowdonia.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มหาวิหารแห่งสันติภาพและศรัทธา สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-snowdonia-8-79',
        'เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน สโนว์โดเนีย (เวลส์คิมรี)',
        'The Midnight Footsteps of Snowdonia (เวลส์คิมรี)',
        'ghost',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.0535,
        -4.0313,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น แคว้นเวลส์ (สหราชอาณาจักร) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ สโนว์โดเนีย',
        'A chilling paranormal account from Wales (United Kingdom). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Snowdonia.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เวลส์คิมรี ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เวลส์คิมรี oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ สโนว์โดเนีย',
        'Never whistle or look back if hearing whispers along twilight pathways in Snowdonia.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
