        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-snowdonia-8-79',
        'พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน สโนว์โดเนีย (เวลส์คิมรี)',
        'The Black-Scaled Serpent of Snowdonia (เวลส์คิมรี)',
        'monster',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.0535,
        -4.0313,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน แคว้นเวลส์ (สหราชอาณาจักร) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ สโนว์โดเนีย',
        'Eyewitness reports of a formidable cryptid stalking Wales (United Kingdom). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Snowdonia.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เวลส์คิมรี ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เวลส์คิมรี folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ สโนว์โดเนีย',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Snowdonia.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

